 public function guard_free_payment_continuation(mixed$order_id):void{if(null===$this->payment)return;$id=is_int($order_id)?$order_id:(is_string($order_id)&&ctype_digit($order_id)?(int)$order_id:0);if($this->payment['stage']->native()['order_id']!==$id)self::refuse();if($this->payment['delegated'])return;if($this->payment['stage']->native()['total']!=='0'||!$this->verify_payment($id,$this->payment['method']))self::refuse();$this->delegating($id);}
 public function guard_store_payment_context(mixed$context,mixed$result):void{unset($result);if(null===$this->payment)return;if(!is_object($context)||get_class($context)!=='Automattic\\WooCommerce\\StoreApi\\Payments\\PaymentContext')self::refuse();$order=$context->order;$method=$context->payment_method;if(!$order instanceof \WC_Order||!is_string($method)||$order!==$this->payment['stage']->order()||$order->get_id()!==$this->payment['stage']->native()['order_id']||!$this->verify_payment($order->get_id(),$method))self::refuse();}
 private function coordinate(\WC_Order$order):string{$site=$GLOBALS['blog_id']??null;$id=$order->get_id();if(!is_int($site)||$site<1||!is_int($id)||$id<1)self::refuse();return$site.':'.$id;}
 private static function message():string{return'Customer policies need review before payment. Return to your cart and try again.';}
 private static function refuse():never{throw new \RuntimeException(self::message());}
